<script setup lang="ts">
import { reactive,ref } from 'vue'
import { ElMessage } from 'element-plus'
import { api,errorText,loadPage } from '../api/http'
import { useAuthStore } from '../stores/auth'
import { positiveInteger } from '../utils/format'
import type { Row } from '../types'
import RemoteSelect from '../components/RemoteSelect.vue'
const auth=useAuthStore(),rows=ref<Row[]>([]),q=ref(''),enabled=ref<boolean>(),page=ref(1),total=ref(0),loading=ref(false),error=ref(''),drawer=ref(false),readOnly=ref(false),busy=ref(false),formError=ref(''),selected=ref<Row|null>(null)
const form=reactive<Row>({code:'',name:'',productMaterialId:'',enabled:true,items:[]})
async function load(){loading.value=true;error.value='';try{const data=await loadPage<Row>('/boms',{q:q.value||undefined,enabled:enabled.value,page:page.value,size:20});rows.value=data.items;total.value=Number(data.total)}catch(e){error.value=errorText(e)}finally{loading.value=false}}
async function open(row?:Row,view=false){formError.value='';readOnly.value=view;try{selected.value=row?(await api.get(`/boms/${row.id}`)).data:null;Object.assign(form,selected.value?{code:selected.value.code,name:selected.value.name,productMaterialId:selected.value.productMaterialId,enabled:selected.value.enabled,items:selected.value.items.map((item:Row)=>({materialId:item.materialId,quantityPer:item.quantityPer}))}:{code:'',name:'',productMaterialId:'',enabled:true,items:[{materialId:'',quantityPer:'1'}]});drawer.value=true}catch(e){error.value=errorText(e)}}
async function save(){if(busy.value)return;const ids=form.items.map((item:Row)=>item.materialId);if(!form.code.trim()||!form.name.trim()||!form.productMaterialId||ids.length<1||ids.some((id:string)=>!id)||new Set(ids).size!==ids.length||form.items.some((item:Row)=>!positiveInteger(item.quantityPer))){formError.value='请完整填写 BOM、成品及不重复的原料，单耗须为正整数';return}busy.value=true;formError.value='';try{const body:Row={code:form.code,name:form.name,productMaterialId:form.productMaterialId,enabled:form.enabled,items:form.items.map((item:Row)=>({materialId:item.materialId,quantityPer:item.quantityPer}))};if(selected.value){body.version=selected.value.version;await api.put(`/boms/${selected.value.id}`,body)}else await api.post('/boms',body);drawer.value=false;ElMessage.success('BOM 已保存');await load()}catch(e){formError.value=errorText(e)}finally{busy.value=false}}
void load()
</script>
<template><div class="page-header"><div><h1>单层 BOM</h1></div><el-button v-if="auth.can('mes:bom:write')" type="primary" @click="open()">新建 BOM</el-button></div><section class="panel"><form class="filters" @submit.prevent="page=1;load()"><el-input v-model="q" placeholder="搜索编码或名称" aria-label="搜索编码或名称" clearable/><el-select v-model="enabled" placeholder="全部状态" clearable aria-label="BOM启用状态"><el-option label="启用" :value="true"/><el-option label="停用" :value="false"/></el-select><el-button type="primary" native-type="submit">查询</el-button><el-button @click="q='';enabled=undefined;page=1;load()">重置</el-button></form><div v-if="error" class="error-box">{{error}} <el-button link @click="load">重试</el-button></div><el-table :data="rows" v-loading="loading" empty-text="暂无 BOM"><el-table-column prop="code" label="BOM 编码" min-width="180"/><el-table-column prop="name" label="名称" min-width="180"/><el-table-column prop="productName" label="成品" min-width="170"/><el-table-column prop="revision" label="修订标记" width="100"/><el-table-column label="原料种类" width="100" align="right"><template #default="{row}">{{row.items.length}}</template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}"><el-tag size="small" :type="row.enabled?'success':'info'">{{row.enabled?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column label="操作" width="130" fixed="right"><template #default="{row}"><el-button link type="primary" @click="open(row,true)">查看</el-button><el-button v-if="auth.can('mes:bom:write')" link @click="open(row)">编辑</el-button></template></el-table-column></el-table><div class="table-footer"><span>同一成品最多一个启用 BOM</span><el-pagination v-model:current-page="page" :total="total" :page-size="20" layout="total,prev,pager,next" @current-change="load"/></div></section><el-drawer v-model="drawer" :title="`${readOnly?'查看':selected?'编辑':'新建'} BOM`" size="min(660px,100%)" destroy-on-close><el-alert v-if="formError" :title="formError" type="error" :closable="false"/><el-form label-position="top" :disabled="readOnly" @submit.prevent="save"><div class="form-grid"><el-form-item label="BOM 编码" required><el-input v-model="form.code" aria-label="BOM 编码" :maxlength="50" :disabled="!!selected"/></el-form-item><el-form-item label="BOM 名称" required><el-input v-model="form.name" aria-label="BOM 名称" :maxlength="120"/></el-form-item><el-form-item label="成品物料" required class="full"><RemoteSelect v-model="form.productMaterialId" resource-path="/materials" :params="{type:'FINISHED_GOOD'}" placeholder="选择成品物料" :disabled="!!selected||readOnly"/></el-form-item><el-form-item label="启用"><el-switch v-model="form.enabled"/></el-form-item></div><h3>生产 1 台所需原料</h3><div v-for="(item,index) in form.items" :key="index" class="bom-line"><div><label class="section-note">原料 {{Number(index)+1}}</label><RemoteSelect v-model="item.materialId" resource-path="/materials" :params="{type:'RAW_MATERIAL'}" :placeholder="`选择原料 ${Number(index)+1}`" :disabled="readOnly"/></div><div><label class="section-note">单耗（正整数）</label><el-input v-model="item.quantityPer" :aria-label="`单耗 ${Number(index)+1}`" inputmode="numeric"/></div><el-button v-if="!readOnly" :disabled="form.items.length===1" text type="danger" @click="form.items.splice(index,1)">移除</el-button></div><el-button v-if="!readOnly" :disabled="form.items.length>=100" @click="form.items.push({materialId:'',quantityPer:'1'})">添加原料</el-button><p class="section-note">修订仅影响后续确认的工单，不会改写历史用料快照。</p><div v-if="!readOnly" class="form-footer"><el-button @click="drawer=false">取消</el-button><el-button type="primary" native-type="submit" :loading="busy">保存 BOM</el-button></div></el-form></el-drawer></template>
<style scoped>.bom-line{display:grid;grid-template-columns:minmax(0,1fr) 130px 55px;gap:12px;align-items:end;margin:18px 0}.bom-line label{display:block;margin-bottom:6px}@media(max-width:650px){.bom-line{grid-template-columns:1fr 85px 48px;gap:6px}}</style>
